            ['start_time' => 350.294, 'end_time' => 352.294, 'target_text' => 'Make it easy on one another.', 'source_text' => 'Permudahkanlah urusan antara satu sama lain.', 'order' => 91],
            ['start_time' => 352.394, 'end_time' => 353.594, 'target_text' => 'Some people have a misnotion.', 'source_text' => 'Sesetengah orang mempunyai salah faham.', 'order' => 92],
            ['start_time' => 353.694, 'end_time' => 357.394, 'target_text' => 'You see little kids, it\'s difficult to talk to them.', 'source_text' => 'Anda lihat anak-anak kecil, sememangnya sukar untuk berbual panjang dengan mereka.', 'order' => 93],
            ['start_time' => 357.494, 'end_time' => 359.594, 'target_text' => 'Try and hold a discussion with them on the phone.', 'source_text' => 'Cubalah berbual dengan mereka melalui panggilan telefon.', 'order' => 94],
            ['start_time' => 359.694, 'end_time' => 365.194, 'target_text' => 'They are more interested in the games on the phone than the person talking on the other side of the phone, right?', 'source_text' => 'Mereka lebih berminat dengan permainan video di dalam telefon tersebut berbanding orang yang sedang bercakap di hujung talian, betul bukan?', 'order' => 95],
            ['start_time' => 365.294, 'end_time' => 368.395, 'target_text' => 'So they talk to you for two minutes, three minutes.', 'source_text' => 'Maka mereka hanya mampu berbual dengan anda selama dua atau tiga minit sahaja.', 'order' => 96],
