            ['start_time' => 391.195, 'end_time' => 392.995, 'target_text' => 'I did not even have any pleasantries.', 'source_text' => 'saya tidak menggunakan sebarang kata-kata basa-basi,', 'order' => 103],
            ['start_time' => 393.095, 'end_time' => 398.195, 'target_text' => 'I dived straight into the core of the topic because I know I have three seconds to catch your attention.', 'source_text' => 'saya terus terjun ke inti pati tajuk kerana saya tahu saya hanya mempunyai masa tiga saat untuk menarik perhatian anda.', 'order' => 104],
            ['start_time' => 398.295, 'end_time' => 399.195, 'target_text' => 'That\'s all.', 'source_text' => 'Hanya itu sahaja masa yang ada.', 'order' => 105],
            ['start_time' => 399.295, 'end_time' => 400.795, 'target_text' => 'And that\'s what I had to do.', 'source_text' => 'Dan itulah yang perlu saya lakukan.', 'order' => 106],
            ['start_time' => 400.895, 'end_time' => 404.695, 'target_text' => 'So if I have to do that to adults, imagine what you got to do to children.', 'source_text' => 'Maka jika terhadap orang dewasa pun saya perlu berbuat demikian, bayangkanlah apa yang perlu anda hadapi dengan kanak-kanak.', 'order' => 107],
            ['start_time' => 404.795, 'end_time' => 406.595, 'target_text' => 'So then they start saying, no, do you know what?', 'source_text' => 'Lalu mulalah timbul tuduhan: \'Awak tahu tak, sebenarnya', 'order' => 108],
