            ['start_time' => 408.695, 'end_time' => 409.295, 'target_text' => 'That\'s wrong.', 'source_text' => 'Tuduhan itu adalah salah.', 'order' => 110],
            ['start_time' => 409.395, 'end_time' => 411.595, 'target_text' => 'No one poisons anyone against anyone.', 'source_text' => 'Tiada sesiapa yang meracuni fikiran sesiapa terhadap mana-mana pihak.', 'order' => 111],
            ['start_time' => 411.695, 'end_time' => 414.995, 'target_text' => 'And if someone is saying nasty things, be careful.', 'source_text' => 'Dan sekiranya ada yang menuturkan kata-kata yang tidak elok, berhati-hatilah.', 'order' => 112],
