            ['start_time' => 450.695, 'end_time' => 453.695, 'target_text' => 'Well, you got to know that your ex is also a parent of these children.', 'source_text' => 'Anda perlu sedar bahawa bekas pasangan anda juga merupakan ibu atau bapa kepada anak-anak ini.', 'order' => 128],
            ['start_time' => 453.795, 'end_time' => 456.495, 'target_text' => 'Keep them access or custody or whatever else.', 'source_text' => 'Berikanlah mereka hak untuk bertemu, hak penjagaan, atau apa jua hak yang sewajarnya.', 'order' => 129],
            ['start_time' => 456.595, 'end_time' => 459.995, 'target_text' => 'And that\'s part of your takdir and your destiny.', 'source_text' => 'Dan itu semua adalah sebahagian daripada takdir serta ketentuan Ilahi buat anda.', 'order' => 130],
            ['start_time' => 460.095, 'end_time' => 462.595, 'target_text' => 'May Allah Almighty protect us.', 'source_text' => 'Semoga Allah Yang Maha Kuasa melindungi kita semua.', 'order' => 131],
            ['start_time' => 462.695, 'end_time' => 463.395, 'target_text' => 'Okay.', 'source_text' => 'Baiklah.', 'order' => 132],
            ['start_time' => 463.495, 'end_time' => 466.195, 'target_text' => 'So imagine', 'source_text' => 'Maka bayangkanlah,', 'order' => 133],
