            ['start_time' => 471.295, 'end_time' => 474.595, 'target_text' => 'The same way it will resolve with others as well.', 'source_text' => 'Dengan kaedah yang sama seperti mana ia diselesaikan dengan orang lain juga.', 'order' => 135],
            ['start_time' => 474.695, 'end_time' => 476.695, 'target_text' => 'Number one, you need to be sincere.', 'source_text' => 'Nombor satu, anda perlu benar-benar ikhlas.', 'order' => 136],
            ['start_time' => 476.795, 'end_time' => 479.195, 'target_text' => 'Do you want to solve the problem?', 'source_text' => 'Adakah anda benar-benar ikhlas ingin menyelesaikan masalah tersebut?', 'order' => 137],
            ['start_time' => 479.295, 'end_time' => 483.395, 'target_text' => 'If you don\'t have sincerity, it\'s not going to be resolved.', 'source_text' => 'Sekiranya anda tiada keikhlasan, masalah itu tidak akan pernah dapat diselesaikan.', 'order' => 138],
            ['start_time' => 483.495, 'end_time' => 488.297, 'target_text' => 'says in the Quran regarding the dispute between husband and wife.', 'source_text' => 'Allah berfirman di dalam al-Quran mengenai perselisihan antara suami dan isteri:', 'order' => 139],
